android.extraProguardRules:
# R8 is enabled for release builds, so anything resolved by name at
# runtime has to be named here. React Native, Expo modules and
# Reanimated each ship their own consumer rules, which Gradle applies
# automatically; these cover the gaps in this app's dependency set.

# Skia and Gesture Handler ship no consumer rules of their own. Both
# reach their Java classes from C++ through JNI, where a renamed class
# cannot be found and fails at runtime rather than at build time.
-keep class com.shopify.reactnative.skia.** { *; }
-keep class com.swmansion.gesturehandler.** { *; }

# JNI lookups by name across the React Native bridge.
-keepclasseswithmembernames class * {
    native <methods>;
}
